// Generates every harness catalog from marketplace.config.ts.
//
//   node scripts/build.ts            write the generated files
//   node scripts/build.ts --check    fail if any committed file is stale (for CI)
//   --config <file>                  use another config (default: marketplace.config.ts)
//   --out <dir>                      write into another directory (default: repo root)
//
// Needs Node >= 22.18, which runs TypeScript directly by stripping types. No dependencies.

import { existsSync } from 'node:fs';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import type { MarketplaceConfig, PluginDef, PluginSource } from './types.ts';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const OPENCODE_HEADER = `// GENERATED by scripts/build.ts from marketplace.config.ts. Do not edit by hand.
// The closest thing to a "marketplace" for opencode is just an opencode config snippet
// with plugin configuration lines that an agent can pick-and-choose to add to the user's
// opencode config as requested.
`;

// ---------- small helpers ----------

type Json = Record<string, unknown>;

/** Drop keys whose value is undefined so the output stays minimal and stable. */
function compact(obj: Json): Json {
  return Object.fromEntries(Object.entries(obj).filter(([, v]) => v !== undefined));
}

function json(value: unknown): string {
  return `${JSON.stringify(value, null, 2)}\n`;
}

/** "plugins/x/" or "./plugins/x" -> "./plugins/x" */
function rel(p: string): string {
  return `./${p.replace(/^\.\//, '').replace(/\/+$/, '')}`;
}

function gitUrl(s: { type: 'github'; repo: string } | { type: 'git'; url: string }): string {
  return s.type === 'github' ? `https://github.com/${s.repo}.git` : s.url;
}

function pin(s: { ref?: string; sha?: string }): Json {
  return compact({ ref: s.ref, sha: s.sha });
}

const KEBAB = /^[a-z0-9]+(?:[-.][a-z0-9]+)*$/;
const SHA = /^[0-9a-f]{40}$/;
const GH_REPO = /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/;

// ---------- validation ----------

function validate(cfg: MarketplaceConfig, root: string): { errors: string[]; warnings: string[] } {
  const errors: string[] = [];
  const warnings: string[] = [];
  if (!KEBAB.test(cfg.name)) errors.push(`marketplace name "${cfg.name}" must be lowercase kebab-case`);
  if (!cfg.owner?.name) errors.push('owner.name is required');

  const seen = new Set<string>();
  for (const p of cfg.plugins) {
    const where = `plugin "${p.name}"`;
    if (!KEBAB.test(p.name)) errors.push(`${where}: name must be lowercase kebab-case`);
    if (seen.has(p.name)) errors.push(`${where}: duplicate name`);
    seen.add(p.name);

    const s = p.source;
    if (s.type === 'github' && !GH_REPO.test(s.repo)) errors.push(`${where}: github repo must be "owner/repo"`);
    if (s.type === 'git' && !/^(https?:\/\/|git@|ssh:\/\/)/.test(s.url)) errors.push(`${where}: git url must be https, ssh or git@`);
    if ((s.type === 'github' || s.type === 'git') && s.sha !== undefined && !SHA.test(s.sha)) {
      errors.push(`${where}: sha must be a full 40-character lowercase commit hash`);
    }
    if ((s.type === 'github' || s.type === 'git' || s.type === 'local') && s.path !== undefined) {
      if (path.isAbsolute(s.path) || s.path.split('/').includes('..')) errors.push(`${where}: path must be relative with no ".."`);
    }
    if (s.type === 'local' && !existsSync(path.join(root, s.path))) errors.push(`${where}: local path ${s.path} does not exist`);

    if (s.type !== 'local' && !p.exclude?.includes('cursor')) {
      warnings.push(`${where}: not listed for Cursor (Cursor only accepts folders inside this repo)`);
    }
    if (p.pi !== undefined && (p.pi === true || p.pi.source === undefined)) {
      if (s.type === 'local') errors.push(`${where}: pi needs an explicit pi.source for a local plugin`);
      if ((s.type === 'github' || s.type === 'git') && s.path) {
        errors.push(`${where}: pi cannot install a subdirectory; set pi.source explicitly`);
      }
    }
  }
  return { errors, warnings };
}

// ---------- per-harness source shapes ----------

function claudeSource(s: PluginSource): unknown {
  switch (s.type) {
    case 'local':
      return rel(s.path);
    case 'npm':
      return compact({ source: 'npm', package: s.package, version: s.version, registry: s.registry });
    case 'github':
    case 'git':
      if (s.path) return { source: 'git-subdir', url: gitUrl(s), path: s.path.replace(/^\.\//, ''), ...pin(s) };
      return s.type === 'github'
        ? { source: 'github', repo: s.repo, ...pin(s) }
        : { source: 'url', url: s.url, ...pin(s) };
  }
}

function codexSource(s: PluginSource): unknown {
  switch (s.type) {
    case 'local':
      return { source: 'local', path: rel(s.path) };
    case 'npm':
      return compact({ source: 'npm', package: s.package, version: s.version, registry: s.registry });
    case 'github':
    case 'git':
      if (s.path) return { source: 'git-subdir', url: gitUrl(s), path: rel(s.path), ...pin(s) };
      return { source: 'url', url: gitUrl(s), ...pin(s) };
  }
}

function piSource(p: PluginDef): string {
  if (p.pi !== true && p.pi?.source) return p.pi.source;
  const s = p.source;
  if (s.type === 'npm') return `npm:${s.package}${s.version ? `@${s.version}` : ''}`;
  if (s.type === 'github' || s.type === 'git') {
    const host = s.type === 'github' ? `github.com/${s.repo}` : s.url.replace(/^https?:\/\//, '').replace(/\.git$/, '');
    const at = s.sha ?? s.ref;
    return `git:${host}${at ? `@${at}` : ''}`;
  }
  throw new Error(`plugin "${p.name}": cannot derive a pi source`); // caught earlier by validate()
}

// ---------- catalog builders ----------

function included(p: PluginDef, t: 'claude' | 'codex' | 'cursor'): boolean {
  return !p.exclude?.includes(t);
}

function header(cfg: MarketplaceConfig): Json {
  return compact({
    name: cfg.name,
    owner: compact({ ...cfg.owner }),
    metadata: cfg.description ? { description: cfg.description } : undefined,
  });
}

function buildOutputs(cfg: MarketplaceConfig): Map<string, string> {
  const out = new Map<string, string>();

  out.set(
    '.claude-plugin/marketplace.json',
    json({
      ...header(cfg),
      plugins: cfg.plugins
        .filter((p) => included(p, 'claude'))
        .map((p) =>
          compact({
            name: p.name,
            source: claudeSource(p.source),
            description: p.description,
            version: p.version,
            category: p.category,
            tags: p.tags,
            ...p.claude,
          }),
        ),
    }),
  );

  out.set(
    '.agents/plugins/marketplace.json',
    json({
      name: cfg.name,
      interface: { displayName: cfg.displayName ?? cfg.name },
      plugins: cfg.plugins
        .filter((p) => included(p, 'codex'))
        .map((p) => ({
          name: p.name,
          source: codexSource(p.source),
          policy: {
            installation: p.codex?.installation ?? 'AVAILABLE',
            authentication: p.codex?.authentication ?? 'ON_INSTALL',
          },
          category: p.codex?.category ?? 'Productivity',
        })),
    }),
  );

  out.set(
    '.cursor-plugin/marketplace.json',
    json({
      ...header(cfg),
      plugins: cfg.plugins
        .filter((p) => included(p, 'cursor') && p.source.type === 'local')
        .map((p) =>
          compact({
            name: p.name,
            source: rel((p.source as { path: string }).path),
            description: p.description,
            version: p.version,
            category: p.category,
            tags: p.tags,
          }),
        ),
    }),
  );

  const opencode = cfg.plugins
    .filter((p) => p.opencode)
    .map((p) => {
      const o = p.opencode!;
      const spec = `${o.package}${o.version ? `@${o.version}` : ''}`;
      return o.options ? { package: spec, options: o.options } : spec;
    });
  out.set('opencode/opencode.jsonc', OPENCODE_HEADER + json({ $schema: 'https://opencode.ai/config.json', plugins: opencode }));

  out.set('pi/packages.json', json({ packages: cfg.plugins.filter((p) => p.pi).map(piSource) }));

  return out;
}

// ---------- main ----------

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] : undefined;
}

async function main(): Promise<void> {
  const check = process.argv.includes('--check');
  const configPath = path.resolve(arg('--config') ?? path.join(ROOT, 'marketplace.config.ts'));
  const outDir = path.resolve(arg('--out') ?? ROOT);

  const mod = (await import(pathToFileURL(configPath).href)) as { default: MarketplaceConfig };
  const cfg = mod.default;

  const { errors, warnings } = validate(cfg, ROOT);
  for (const w of warnings) console.warn(`warning: ${w}`);
  if (errors.length) {
    for (const e of errors) console.error(`error: ${e}`);
    process.exit(1);
  }

  const stale: string[] = [];
  for (const [relPath, content] of buildOutputs(cfg)) {
    const file = path.join(outDir, relPath);
    const current = existsSync(file) ? await readFile(file, 'utf8') : undefined;
    if (current === content) continue;
    if (check) {
      stale.push(relPath);
    } else {
      await mkdir(path.dirname(file), { recursive: true });
      await writeFile(file, content);
      console.log(`wrote ${relPath}`);
    }
  }

  if (check && stale.length) {
    console.error(`stale generated files (run: node scripts/build.ts):\n  ${stale.join('\n  ')}`);
    process.exit(1);
  }
  console.log(check ? 'generated files are up to date' : `done: ${cfg.plugins.length} plugin(s)`);
}

await main();
